public class ThermostatDemo {

    static class Thermostat {
        private int temperature;
        private boolean ecoMode;

        public Thermostat(int temperature, boolean ecoMode) {
            this.temperature = temperature;
            this.ecoMode = ecoMode;
        }

        public String getStatus() {
            int threshold = ecoMode ? 65 : 70;
            if (temperature < threshold) {
                return "Heating";
            }
            return "Idle";
        }

        public String printStatusToDisplay() {
            return "Thermostat status: " + getStatus();
        }
    }

    public static void main(String[] args) {
        Thermostat thermostat = new Thermostat(68, false);
        System.out.println(thermostat.printStatusToDisplay());
    }
}
